local a=peripheral.find("modem")local b=require("index")local c=require("commands")local d=b.create()local function e(f)local g=a.callRemote(f,"size")for h=1,g do local i=a.callRemote(f,"getItemDetail",h)if i==nil then return true end end;return false end;local function j(k,l,h)local m=b.getReceiver(d,k)if m==nil then return end;if e(m)then a.callRemote(l,"pushItems",m,h)print("Transferred from "..l.." to "..k)else print("No empty slots available in receiver "..k)end end;local function n(o)for h,i in pairs(a.callRemote(o,"list"))do if i==nil then goto p end;local q=a.callRemote(o,"getItemDetail",h)local r=q.package;if r==nil then j("MainItem",o,h)else local k=r.getAddress()if k~=nil then j(k,o,h)else print("No address found for item in slot "..h.." of sender "..o)end end::p::end end;local function s()while true do local t=b.getAllSenders(d)if#t==0 then print("No senders found in index.")sleep(5)break end;for u,o in ipairs(t)do n(o)end end end;if#arg>0 then if arg[1]=="mapping"then print("Mapping")c.processCommandLoop(d)end end;print("Transferring")s()
